-- run on sitedb server got issue

--MUST Input SessionID, transid, SettlementAction from SiteDB_SettlementProcessing, then get all related logID
DECLARE @SessionId BIGINT = NULL, @SiteDBGroupId SMALLINT, @SettlementAction VARCHAR(20), @TransInfo VARBINARY(MAX), @Decompress_TransInfoJson NVARCHAR(MAX)

SELECT @SessionId = xxx, @SiteDBGroupId = xxx, @SettlementAction = xxx, @TransInfo = xxx
--SAMPE input param
--SELECT @SessionId = 268195, @SiteDBGroupId = 1, @SettlementAction = 'CAL', @TransInfo = 

SET @Decompress_TransInfoJson = CAST(DECOMPRESS(@TransInfo) AS NVARCHAR(MAX))

CREATE TABLE #temp (TransID BIGINT)
INSERT INTO #temp (TransID)
SELECT t as transid
FROM OPENJSON(@Decompress_TransInfoJson)
WITH (
t   BIGINT
--,m  VARCHAR(11)
--,o  SMALLMONEY	
--,os  VARCHAR(20)
--,statuswl  VARCHAR(1)
--,st  DATETIME
--,w  MONEY
--,aw  MONEY
--,mw  MONEY
--,sw  MONEY
--,pc  MONEY
--,c  MONEY
--,ac  MONEY
--,sc  MONEY
--,s  NVARCHAR(10)
--,sid  TINYINT
--,r  TINYINT
)

SELECT C.*
FROM SiteDB_SettlementService_CalculationLog c WITH (NOLOCK)
	CROSS APPLY (SELECT TOP 1 1 AS valid
				FROM OPENJSON(DECOMPRESS(c.transinfoJson))
					WITH (
							t   BIGINT
					) AS i
				INNER JOIN #temp tmp ON tmp.TransID = i.t

			) AS temp

WHERE SessionId = @SessionId  AND SettlementAction = @SettlementAction

DROP TABLE #temp
